import { NextResponse } from 'next/server';

let withdrawals = [
    { id: "REQ-001", userId: 3, userName: "Helio Vendedor", amount: 1500.00, date: "2026-02-20", status: "Pendente", pix: "helio@test.com" },
    { id: "REQ-002", userId: 2, userName: "Maria Oliveira", amount: 800.00, date: "2026-02-18", status: "Pago", pix: "maria@pix.com" },
];

export async function GET() {
    return NextResponse.json(withdrawals);
}

export async function PUT(request: Request) {
    const data = await request.json();
    const { id, status } = data;

    const index = withdrawals.findIndex(w => w.id === id);
    if (index === -1) return NextResponse.json({ error: "Request not found" }, { status: 404 });

    withdrawals[index].status = status;
    return NextResponse.json(withdrawals[index]);
}
